import{at as e,it as t,n,vt as r}from"./chunks/framework.B6nQ8gjX.js";var i=JSON.parse(`{"title":"历史记录","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 搜索记录（Search History）","slug":"_1-搜索记录-search-history","link":"#_1-搜索记录-search-history","children":[]},{"level":2,"title":"2. 关键字记录（Keyword History）","slug":"_2-关键字记录-keyword-history","link":"#_2-关键字记录-keyword-history","children":[]},{"level":2,"title":"3. 查询关联（Query Associations）","slug":"_3-查询关联-query-associations","link":"#_3-查询关联-query-associations","children":[]}],"relativePath":"zh-CN/user-guide/settings/history.md","filePath":"zh-CN/user-guide/settings/history.md","lastUpdated":1795268921000}`),a={name:`zh-CN/user-guide/settings/history.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="历史记录" tabindex="-1">历史记录 <a class="header-anchor" href="#历史记录" aria-label="Permalink to “历史记录”">​</a></h1><p>三个标签页分别管理打开记录、搜索关键词和查询关联。</p><h2 id="_1-搜索记录-search-history" tabindex="-1">1. 搜索记录（Search History） <a class="header-anchor" href="#_1-搜索记录-search-history" aria-label="Permalink to “1. 搜索记录（Search History）”">​</a></h2><p>记录从搜索结果中打开文件、文件夹或应用程序的次数与时间。</p><ul><li><strong>排序加权</strong>：每次打开加 1 分，上限 10 分，90 天减半。有效分达到 3 可进入 H3 档，达到 5 可进入 H5 档。快速搜索最多分配 3 个 H5、10 个 H3 名额，内嵌搜索为 1 个和 3 个，完整窗口不限制名额。</li><li><strong>前移范围</strong>：历史权重可让条目超过同一有效匹配等级、同一优先级的其他结果。快速搜索的类型设置会影响文件、文件夹的完整匹配等级，详见<a href="./../search-syntax.html">搜索语法</a>。</li><li><strong>内嵌分区</strong>：当前文件夹与全局结果分别显示。不存在的路径会被跳过。</li><li><strong>管理操作</strong>：可按关键词筛选、单条删除、清除使用次数不超过 N 的记录或清空全部。其他窗口新增打开记录后，列表会刷新。关闭记录开关后不再添加新条目，已有条目仍更新次数和最近时间。</li></ul><h2 id="_2-关键字记录-keyword-history" tabindex="-1">2. 关键字记录（Keyword History） <a class="header-anchor" href="#_2-关键字记录-keyword-history" aria-label="Permalink to “2. 关键字记录（Keyword History）”">​</a></h2><p>执行结果或动作、打开完整窗口时，记录搜索框中的原始查询。仅输入文字后关闭快速搜索，不会新增记录。</p><ul><li>按 <strong>Alt+Up / Alt+Down</strong> 翻阅最近搜索词，按 <strong>Ctrl+Delete</strong> 删除当前词条。</li><li>可筛选、单条删除、清空全部，或按使用次数清理。本页有独立的记录开关；关闭后不再添加新词，已有词条仍累加次数。</li></ul><h2 id="_3-查询关联-query-associations" tabindex="-1">3. 查询关联（Query Associations） <a class="header-anchor" href="#_3-查询关联-query-associations" aria-label="Permalink to “3. 查询关联（Query Associations）”">​</a></h2><p>独立保存<strong>查询词 → 目标路径</strong>关联。</p><ul><li>同一规范化查询下，从正常搜索结果打开目标至少 <strong>3 次</strong>后，关联才可用于补充结果。仅靠关联找出的条目再次被打开，不会增加确认次数。</li><li>每次查询最多补充 <strong>1 条</strong>关联，不补充低优先级目标。仅靠关联找出的结果排在直接匹配之后。</li><li>可筛选、单条删除或清空关联，路径使用分数会保留。</li></ul>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};